import { z } from 'zod';
import { zodResolver, createResource } from 'qortex-resource';

const InvoiceSchema = z.object({
  customerId: z.string().min(1),
  lineItems: z.array(z.object({
    sku: z.string().min(1),
    qty: z.number().int().positive(),
    unitPrice: z.number().nonnegative(),
  })).min(1, 'Add at least one line'),
});

const invoice = createResource({
  validate: { resolver: zodResolver(InvoiceSchema), on: 'blur' },
  source: { save: (d) => api.invoices.save(d) },
  initialData: {
    customerId: '',
    lineItems: [{ sku: '', qty: 1, unitPrice: 0 }],
  },
});

await invoice.validateField('lineItems.0.sku');
await invoice.validate(); // full schema

function LineItems({ resource }) {
  const { fields, append, remove, move } = useFieldArray(resource, 'lineItems');

  return (
    <section>
      <h2>Line items</h2>
      {fields.map((row) => (
        <div key={row.id} style={{ display: 'flex', gap: 8 }}>
          <Field resource={resource} path={`lineItems.${row.index}.sku`} />
          <Field resource={resource} path={`lineItems.${row.index}.qty`} type="number" />
          <Field resource={resource} path={`lineItems.${row.index}.unitPrice`} type="number" />
          <button type="button" onClick={() => remove(row.index)}>×</button>
          {row.index > 0 && (
            <button type="button" onClick={() => move(row.index, row.index - 1)}>↑</button>
          )}
        </div>
      ))}
      <button
        type="button"
        onClick={() => append({ sku: '', qty: 1, unitPrice: 0 })}
      >
        Add line
      </button>
    </section>
  );
}

function Field({ resource, path, type = 'text' }) {
  const { value, error, onChange, onBlur } = useField(resource, path);
  return (
    <label>
      <input
        type={type}
        value={value ?? ''}
        onChange={(e) =>
          onChange(type === 'number' ? Number(e.target.value) : e.target.value)
        }
        onBlur={onBlur}
      />
      {error && <small>{error}</small>}
    </label>
  );
}
